#include "factory_lease.hpp"
#include <cassert>
#include <cstdio>
using namespace supra;
static void put(FactoryLease::Packet& b,unsigned v){for(int i=3;i>=0;--i)b.push_back((v>>(i*8))&255);}
static FactoryLease::Packet message(unsigned role,unsigned method,unsigned seq,bool idle){FactoryLease::Packet b;put(b,role?100:200);if(method==9){put(b,role?101:0x21000000);b.push_back(role?46:33);put(b,role?9:42);put(b,role?3:2);put(b,role?101:0x21000000);b.push_back(role?46:33);if(role)put(b,idle?0xffffffff:109);else {put(b,0xffffffff);put(b,0xffffffff);b.push_back(idle?0:2);for(unsigned i=0;i<28;++i)b.push_back(0);}}FactoryLease::Packet p;p.push_back(0xb0);p.push_back(role?14:6);p.push_back(0);p.push_back(method);put(p,b.size()+8);p.push_back(0);p.push_back(1);p.push_back(seq>>8);p.push_back(seq&255);p.push_back(1);p.push_back(1);p.push_back(0);p.push_back(0);p.insert(p.end(),b.begin(),b.end());return p;}
static void complete(FactoryLease& l,const FactoryLease::Packet& p){assert(l.outgoing(p));FactoryLease::Packet ack(p.begin(),p.begin()+16);ack[4]=ack[5]=ack[6]=0;ack[7]=8;ack[14]=128;assert(l.reply(ack));}
static void set(FactoryLease& l,unsigned role,unsigned seq,bool idle){FactoryLease::Packet p=message(role,9,seq,idle);assert(l.before(p,role));complete(l,p);p=message(role,4,seq+1,idle);assert(l.before(p,role));assert(!l.available());complete(l,p);}
int main(){FactoryLease l;assert(!l.available());set(l,0,1,true);assert(!l.available());set(l,1,3,true);assert(l.available());set(l,1,5,false);assert(!l.available());set(l,0,7,false);set(l,1,9,true);assert(!l.available());set(l,0,11,true);assert(l.available());FactoryLease::Packet p=message(1,9,20,false);assert(l.before(p,1));assert(!l.available());assert(!l.before(p,1));assert(l.failed());FactoryLease u;assert(!u.outgoing(p));assert(u.failed());FactoryLease reordered;set(reordered,0,30,true);set(reordered,1,32,true);FactoryLease::Packet old=message(0,4,40,true),newer=message(0,9,41,false);assert(reordered.before(old,0));assert(reordered.before(newer,0));complete(reordered,old);complete(reordered,newer);assert(!reordered.available());FactoryLease resources;set(resources,0,50,true);set(resources,1,52,true);FactoryLease::Packet resource=message(1,8,54,true);assert(resources.before(resource,1));assert(!resources.available());complete(resources,resource);assert(resources.available());FactoryLease::Packet child=message(0,9,55,false);child[23]=1;assert(resources.before(child,0));assert(!resources.available());complete(resources,child);assert(resources.available());FactoryLease unfinished;FactoryLease::Packet wire=message(0,4,80,true),raw=wire;raw[4]=0x98;raw[5]=0x2e;raw[6]=0x2d;raw[7]=0x17;assert(unfinished.before(raw,0));assert(raw[4]==0x98);complete(unfinished,wire);assert(!unfinished.failed());puts("factory lease tests passed");}
